// Shared wave function so the ocean mesh, the surfboard
// and the spray all agree on where the water surface is.

export function waveHeight(x, z, t) {
  return (
    Math.sin(x * 0.28 + t * 1.4) * 0.55 +
    Math.sin(z * 0.22 - t * 1.1) * 0.40 +
    Math.sin((x + z) * 0.13 + t * 0.7) * 0.25
  );
}

// Numerical slope helpers (used to tilt the surfboard).
export function waveSlopeX(x, z, t, d = 0.35) {
  return (waveHeight(x + d, z, t) - waveHeight(x - d, z, t)) / (2 * d);
}

export function waveSlopeZ(x, z, t, d = 0.35) {
  return (waveHeight(x, z + d, t) - waveHeight(x, z - d, t)) / (2 * d);
}

import * as THREE from "three";
import { waveHeight } from "./waves.js";

// Low-poly faceted ocean. The surface is displaced on the CPU
// every frame; crest vertices get a foamy white vertex color.

export class Ocean {
  constructor(size = 140, segments = 96) {
    this.size = size;
    this.segments = segments;

    const geo = new THREE.PlaneGeometry(size, size, segments, segments);
    geo.rotateX(-Math.PI / 2); // work directly in XZ, Y = up
    this.base = geo.attributes.position.array.slice(); // rest positions

    // Vertex colors for foam on crests.
    const count = geo.attributes.position.count;
    this.colors = new Float32Array(count * 3);
    geo.setAttribute("color", new THREE.BufferAttribute(this.colors, 3));

    const mat = new THREE.MeshStandardMaterial({
      color: 0x1c7f9e,
      flatShading: true,
      vertexColors: true,
      roughness: 0.55,
      metalness: 0.05,
    });

    this.mesh = new THREE.Mesh(geo, mat);
    this.mesh.position.y = -0.6; // ride height offset for the board
  }

  update(t) {
    const pos = this.mesh.geometry.attributes.position;
    const arr = pos.array;
    const base = this.base;
    const colors = this.colors;

    const crest = 0.75; // height above which foam fades in
    const foamSpan = 0.9;

    for (let i = 0; i < pos.count; i++) {
      const ix = i * 3;
      const x = base[ix];
      const z = base[ix + 2];
      const h = waveHeight(x, z, t);
      arr[ix + 1] = h;

      // Foam intensity: whiter near wave crests.
      let f = (h - (crest - foamSpan)) / foamSpan;
      f = Math.max(0, Math.min(1, f));
      // A little noise so foam isn't a clean band.
      f *= 0.65 + 0.35 * Math.sin(x * 3.1 + z * 2.3 + t * 2.0);

      const cix = ix;
      colors[cix] = 0.11 + f * 0.85;
      colors[cix + 1] = 0.5 + f * 0.45;
      colors[cix + 2] = 0.62 + f * 0.36;
    }

    pos.needsUpdate = true;
    this.mesh.geometry.attributes.color.needsUpdate = true;
    this.mesh.geometry.computeVertexNormals();
  }
}

import * as THREE from "three";
import { waveHeight } from "./waves.js";

// Water-spray particle system trailing the surfboard.
// Simple particle pool with gravity, spawn at the board's tail.

export class Spray {
  constructor(count = 220) {
    this.count = count;
    this.positions = new Float32Array(count * 3);
    this.velocities = new Float32Array(count * 3);
    this.life = new Float32Array(count); // 0 = dead

    // Start everything dead, parked far below the sea.
    for (let i = 0; i < count; i++) {
      this.positions[i * 3 + 1] = -1000;
    }

    const geo = new THREE.BufferGeometry();
    geo.setAttribute("position", new THREE.BufferAttribute(this.positions, 3));

    // Round soft sprite generated in code.
    const sprite = makeDropTexture();
    const mat = new THREE.PointsMaterial({
      size: 0.28,
      map: sprite,
      transparent: true,
      depthWrite: false,
      color: 0xeafcff,
      opacity: 0.9,
    });

    this.points = new THREE.Points(geo, mat);
    this.next = 0;
    this.spawnAccumulator = 0;
  }

  spawn(x, y, z, dirX, speed) {
    const i = this.next;
    this.next = (this.next + 1) % this.count;
    const ix = i * 3;
    this.positions[ix] = x + (Math.random() - 0.5) * 0.5;
    this.positions[ix + 1] = y + Math.random() * 0.15;
    this.positions[ix + 2] = z + (Math.random() - 0.5) * 0.6;
    this.velocities[ix] = dirX * (1.2 + Math.random() * speed);
    this.velocities[ix + 1] = 1.4 + Math.random() * 2.2;
    this.velocities[ix + 2] = (Math.random() - 0.5) * 1.6;
    this.life[i] = 0.9 + Math.random() * 0.5;
  }

  update(dt, boardX, boardZ, boardDir, t) {
    // Emit from the board's tail at a steady rate.
    this.spawnAccumulator += dt * 60;
    while (this.spawnAccumulator > 0) {
      this.spawnAccumulator -= 1;
      const y = waveHeight(boardX, boardZ, t) - 0.55;
      this.spawn(boardX - boardDir * 1.3, y, boardZ, -boardDir, 1.5);
    }

    const g = 6.5;
    for (let i = 0; i < this.count; i++) {
      if (this.life[i] <= 0) continue;
      const ix = i * 3;
      this.life[i] -= dt;
      if (this.life[i] <= 0) {
        this.positions[ix + 1] = -1000;
        continue;
      }
      this.velocities[ix + 1] -= g * dt;
      this.positions[ix] += this.velocities[ix] * dt;
      this.positions[ix + 1] += this.velocities[ix + 1] * dt;
      this.positions[ix + 2] += this.velocities[ix + 2] * dt;
    }

    this.points.geometry.attributes.position.needsUpdate = true;
  }
}

function makeDropTexture() {
  const c = document.createElement("canvas");
  c.width = 32;
  c.height = 32;
  const ctx = c.getContext("2d");
  const grad = ctx.createRadialGradient(16, 16, 1, 16, 16, 15);
  grad.addColorStop(0, "rgba(255,255,255,1)");
  grad.addColorStop(0.5, "rgba(255,255,255,0.5)");
  grad.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 32, 32);
  const tex = new THREE.CanvasTexture(c);
  return tex;
}

import * as THREE from "three";

// The star of the show: a pelican built entirely from primitives,
// crouched on a surfboard, wings out for balance, pouch wobbling.

const WHITE = 0xf7f3ea;
const BEAK = 0xf0a13a;
const POUCH = 0xe8734a;
const FEET = 0xd98a2b;
const BOARD = 0xff5a3c;

export class Pelican {
  constructor() {
    this.group = new THREE.Group(); // everything, incl. board
    this.rider = new THREE.Group(); // just the bird (bobs independently)
    this.group.add(this.rider);

    const body = new THREE.Group();
    this.rider.add(body);
    this.body = body;

    const matBody = new THREE.MeshStandardMaterial({
      color: WHITE,
      roughness: 0.8,
      flatShading: true,
    });
    const matDark = new THREE.MeshStandardMaterial({
      color: 0x2b2b33,
      roughness: 0.6,
    });
    const matBeak = new THREE.MeshStandardMaterial({
      color: BEAK,
      roughness: 0.55,
    });
    const matPouch = new THREE.MeshStandardMaterial({
      color: POUCH,
      roughness: 0.6,
    });
    const matFoot = new THREE.MeshStandardMaterial({ color: FEET, roughness: 0.7 });
    const matBoard = new THREE.MeshStandardMaterial({
      color: BOARD,
      roughness: 0.35,
      metalness: 0.1,
    });
    const matStripe = new THREE.MeshStandardMaterial({
      color: 0xfff4e0,
      roughness: 0.4,
    });

    // ---- Surfboard ----
    const board = new THREE.Group();
    board.position.y = 0.0;
    this.group.add(board);
    this.board = board;

    const deck = new THREE.Mesh(new THREE.SphereGeometry(1, 24, 16), matBoard);
    deck.scale.set(2.3, 0.14, 0.62);
    board.add(deck);

    const stripe = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.05, 0.16), matStripe);
    stripe.position.y = 0.13;
    board.add(stripe);

    // Tail fin (skeg) of the surfboard.
    const skeg = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.5, 4), matBoard);
    skeg.position.set(-2.0, -0.2, 0);
    skeg.rotation.z = Math.PI / 2 + 0.35;
    board.add(skeg);

    // ---- Body ----
    const torso = new THREE.Mesh(new THREE.SphereGeometry(0.62, 18, 14), matBody);
    torso.scale.set(1.25, 0.85, 0.95);
    torso.rotation.z = 0.28; // leaning forward
    torso.position.set(0.1, 0.62, 0);
    body.add(torso);

    // Tail feathers.
    const tail = new THREE.Mesh(new THREE.ConeGeometry(0.3, 0.85, 6), matBody);
    tail.position.set(-0.75, 0.58, 0);
    tail.rotation.z = -Math.PI / 2 - 0.35;
    body.add(tail);

    // ---- Neck ----
    const neck = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 0.85, 10), matBody);
    neck.position.set(0.62, 1.05, 0);
    neck.rotation.z = -0.45;
    body.add(neck);

    // ---- Head ----
    const head = new THREE.Group();
    head.position.set(0.98, 1.42, 0);
    body.add(head);
    this.head = head;

    const skull = new THREE.Mesh(new THREE.SphereGeometry(0.24, 16, 12), matBody);
    skull.scale.set(1.15, 1, 0.95);
    head.add(skull);

    // Crest feathers.
    const crest = new THREE.Mesh(new THREE.ConeGeometry(0.1, 0.3, 5), matBody);
    crest.position.set(-0.12, 0.24, 0);
    crest.rotation.z = 0.5;
    head.add(crest);

    // Eyes.
    const eyeGeo = new THREE.SphereGeometry(0.05, 8, 8);
    const eyeL = new THREE.Mesh(eyeGeo, matDark);
    eyeL.position.set(0.15, 0.07, 0.16);
    head.add(eyeL);
    const eyeR = new THREE.Mesh(eyeGeo, matDark);
    eyeR.position.set(0.15, 0.07, -0.16);
    head.add(eyeR);

    // ---- Beak + pouch ----
    const beak = new THREE.Mesh(new THREE.ConeGeometry(0.12, 0.95, 8), matBeak);
    beak.rotation.z = -Math.PI / 2;
    beak.position.set(0.62, -0.02, 0);
    beak.scale.set(1, 1, 0.55);
    head.add(beak);

    this.pouch = new THREE.Mesh(new THREE.SphereGeometry(0.17, 12, 10), matPouch);
    this.pouch.position.set(0.5, -0.16, 0);
    this.pouch.scale.set(1.8, 0.7, 0.5);
    head.add(this.pouch);

    // ---- Wings ----
    const wingGeo = new THREE.BoxGeometry(0.95, 0.06, 0.55);
    const wingTipGeo = new THREE.BoxGeometry(0.5, 0.05, 0.4);

    this.wingL = new THREE.Group();
    this.wingL.position.set(0.05, 0.85, 0.35);
    const wl = new THREE.Mesh(wingGeo, matBody);
    wl.position.set(0.1, 0, 0.32);
    wl.rotation.y = 0.25;
    this.wingL.add(wl);
    const wlTip = new THREE.Mesh(wingTipGeo, matDark);
    wlTip.position.set(0.5, 0, 0.6);
    wlTip.rotation.y = 0.55;
    this.wingL.add(wlTip);
    body.add(this.wingL);

    this.wingR = new THREE.Group();
    this.wingR.position.set(0.05, 0.85, -0.35);
    const wr = new THREE.Mesh(wingGeo, matBody);
    wr.position.set(0.1, 0, -0.32);
    wr.rotation.y = -0.25;
    this.wingR.add(wr);
    const wrTip = new THREE.Mesh(wingTipGeo, matDark);
    wrTip.position.set(0.5, 0, -0.6);
    wrTip.rotation.y = -0.55;
    this.wingR.add(wrTip);
    body.add(this.wingR);

    // ---- Feet ----
    const footGeo = new THREE.BoxGeometry(0.42, 0.06, 0.2);
    const footL = new THREE.Mesh(footGeo, matFoot);
    footL.position.set(0.25, 0.12, 0.18);
    footL.rotation.z = 0.15;
    body.add(footL);
    const footR = new THREE.Mesh(footGeo, matFoot);
    footR.position.set(0.25, 0.12, -0.18);
    footR.rotation.z = 0.15;
    body.add(footR);
  }

  // h: wave height at the board, sx/sz: wave slopes, t: time.
  update(t, h, sx, sz) {
    // Board rides the wave surface.
    this.group.position.y = h - 0.5;
    this.group.rotation.z = -sx * 0.85 + Math.sin(t * 0.9) * 0.03;
    this.group.rotation.x = sz * 0.85;

    // Rider bobbing & carving.
    this.rider.position.y = Math.sin(t * 3.1) * 0.05;
    this.rider.rotation.y = Math.sin(t * 0.7) * 0.12;
    this.rider.rotation.z = Math.sin(t * 1.3) * 0.05;

    // Wing flap: mostly gliding, with a lazy oscillation.
    const flap = Math.sin(t * 2.2) * 0.35 + Math.sin(t * 4.7) * 0.1;
    this.wingL.rotation.x = -0.25 - flap;
    this.wingR.rotation.x = 0.25 + flap;

    // Head looks ahead, occasionally dips toward the water.
    const peek = Math.max(0, Math.sin(t * 0.5));
    this.head.rotation.z = -peek * 0.5;

    // Pouch jiggles in the wind.
    this.pouch.scale.set(1.8 + Math.sin(t * 6) * 0.08, 0.7, 0.5);
  }
}

import * as THREE from "three";
import { Ocean } from "./ocean.js";
import { Pelican } from "./pelican.js";
import { Spray } from "./spray.js";
import { waveHeight, waveSlopeX, waveSlopeZ } from "./waves.js";

// ---- Renderer / scene / camera ----
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
document.getElementById("app").appendChild(renderer.domElement);

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0x9fd8e8, 34, 95);

const camera = new THREE.PerspectiveCamera(
  55,
  window.innerWidth / window.innerHeight,
  0.1,
  300
);

// ---- Sky dome (vertical gradient shader) ----
const sky = new THREE.Mesh(
  new THREE.SphereGeometry(140, 24, 16),
  new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    uniforms: {
      top: { value: new THREE.Color(0x2f8fc4) },
      bottom: { value: new THREE.Color(0xcdeef7) },
    },
    vertexShader: `
      varying vec3 vPos;
      void main() {
        vPos = position;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 top;
      uniform vec3 bottom;
      varying vec3 vPos;
      void main() {
        float h = clamp(normalize(vPos).y * 0.5 + 0.5, 0.0, 1.0);
        gl_FragColor = vec4(mix(bottom, top, pow(h, 0.8)), 1.0);
      }
    `,
  })
);
sky.frustumCulled = false;
scene.add(sky);

// ---- Lights ----
const hemi = new THREE.HemisphereLight(0xbfe8ff, 0x1a5c74, 1.1);
scene.add(hemi);

const sun = new THREE.DirectionalLight(0xfff3d6, 1.6);
sun.position.set(-8, 12, 6);
scene.add(sun);

const ambient = new THREE.AmbientLight(0x88aacc, 0.35);
scene.add(ambient);

// ---- Sun disc ----
const sunDisc = new THREE.Mesh(
  new THREE.SphereGeometry(4, 20, 14),
  new THREE.MeshBasicMaterial({ color: 0xfff2b8, fog: false })
);
sunDisc.position.set(-46, 26, -70);
scene.add(sunDisc);

const sunGlow = new THREE.Mesh(
  new THREE.SphereGeometry(6.2, 20, 14),
  new THREE.MeshBasicMaterial({
    color: 0xffe9a0,
    transparent: true,
    opacity: 0.35,
    fog: false,
  })
);
sunGlow.position.copy(sunDisc.position);
scene.add(sunGlow);

// ---- Clouds (drifting puffs of spheres) ----
const cloudMat = new THREE.MeshStandardMaterial({
  color: 0xffffff,
  roughness: 1,
  flatShading: true,
});
const clouds = [];
for (let i = 0; i < 9; i++) {
  const cloud = new THREE.Group();
  const puffs = 3 + Math.floor(Math.random() * 3);
  for (let j = 0; j < puffs; j++) {
    const r = 1.1 + Math.random() * 1.4;
    const puff = new THREE.Mesh(new THREE.SphereGeometry(r, 10, 8), cloudMat);
    puff.position.set(j * 1.6 - puffs * 0.8, Math.random() * 0.7, Math.random() * 1.2);
    puff.scale.y = 0.55;
    cloud.add(puff);
  }
  const a = Math.random() * Math.PI * 2;
  const d = 40 + Math.random() * 35;
  cloud.position.set(Math.cos(a) * d, 14 + Math.random() * 12, Math.sin(a) * d);
  cloud.userData.speed = 0.25 + Math.random() * 0.4;
  scene.add(cloud);
  clouds.push(cloud);
}

// ---- World ----
const ocean = new Ocean();
scene.add(ocean.mesh);

const pelican = new Pelican();
scene.add(pelican.group);

const spray = new Spray();
scene.add(spray.points);

// Distant gulls (little gliding triangles).
const gullMat = new THREE.MeshBasicMaterial({ color: 0x35424a, side: THREE.DoubleSide });
const gulls = [];
for (let i = 0; i < 5; i++) {
  const gull = new THREE.Group();
  const wingGeo = new THREE.BufferGeometry();
  wingGeo.setAttribute(
    "position",
    new THREE.BufferAttribute(new Float32Array([0, 0, 0, 1.4, 0.25, 0.4, 1.4, 0.25, -0.4]), 3)
  );
  const left = new THREE.Mesh(wingGeo, gullMat);
  const right = new THREE.Mesh(wingGeo, gullMat);
  right.scale.z = -1;
  gull.add(left, right);
  gull.userData = {
    radius: 16 + Math.random() * 12,
    height: 7 + Math.random() * 6,
    speed: 0.15 + Math.random() * 0.2,
    phase: Math.random() * Math.PI * 2,
    flap: 1.5 + Math.random() * 2,
  };
  scene.add(gull);
  gulls.push(gull);
}

// ---- Animation loop ----
const clock = new THREE.Clock();

function animate() {
  requestAnimationFrame(animate);
  const dt = Math.min(clock.getDelta(), 0.05);
  const t = clock.elapsedTime;

  // Board carves a lazy slalom around the origin.
  const bx = Math.sin(t * 0.22) * 7;
  const bz = Math.cos(t * 0.31) * 5;
  const dir = Math.cos(t * 0.22) * 0.22 * 7 - Math.sin(t * 0.31) * 0.31 * 5 * 0; // facing sign
  const facing = Math.cos(t * 0.22) * 0.22 * 7; // d(bx)/dt — used as travel direction

  const h = waveHeight(bx, bz, t);
  const sx = waveSlopeX(bx, bz, t);
  const sz = waveSlopeZ(bx, bz, t);

  pelican.group.position.x = bx;
  pelican.group.position.z = bz;
  pelican.group.rotation.y = facing > 0 ? 0 : Math.PI;
  pelican.update(t, h, sx, sz);

  spray.update(dt, bx, bz, facing >= 0 ? 1 : -1, t);

  ocean.update(t);

  // Clouds drift slowly.
  for (const c of clouds) {
    c.position.x += c.userData.speed * dt;
    if (c.position.x > 85) c.position.x = -85;
  }

  // Gulls circle overhead, wings flapping.
  for (const g of gulls) {
    const u = g.userData;
    const a = t * u.speed + u.phase;
    g.position.set(Math.cos(a) * u.radius, u.height + Math.sin(t * 1.3 + u.phase) * 0.6, Math.sin(a) * u.radius);
    g.rotation.y = -a + Math.PI / 2;
    g.children[0].rotation.x = Math.sin(t * u.flap) * 0.5;
    g.children[1].rotation.x = -Math.sin(t * u.flap) * 0.5;
  }

  // Camera slowly orbits, always watching the pelican.
  const camA = t * 0.11;
  const camDist = 10.5;
  camera.position.set(
    pelican.group.position.x + Math.cos(camA) * camDist,
    4.2 + Math.sin(t * 0.4) * 0.6,
    pelican.group.position.z + Math.sin(camA) * camDist
  );
  camera.lookAt(pelican.group.position.x, pelican.group.position.y + 1.2, pelican.group.position.z);

  // Keep sky dome + sun centred on the camera (infinite backdrop).
  sky.position.copy(camera.position);
  sunDisc.position.set(
    camera.position.x - 46,
    camera.position.y + 22,
    camera.position.z - 70
  );
  sunGlow.position.copy(sunDisc.position);

  renderer.render(scene, camera);
}

window.addEventListener("resize", () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

animate();

